SourceCode.Declaration:
/// <summary>
/// Extension of the <c>WhsDocumentRouting</c> class for the AAXWarehouseTools model. Opens a
/// label capture scope around <c>printDocument</c> and stages each ZPL label passed to
/// <c>printLabelToPrinter</c> while a scope is active.
/// </summary>
[ExtensionOf(classStr(WhsDocumentRouting))]
public final class WhsDocumentRouting_AAXWarehouseTools_Extension
{
}

Method.Source:
/// <summary>
/// Extends <c>printDocument</c> to open a label capture scope for the duration of the print.
/// Capture is active only when the label has a work id and capture is enabled. The base
/// implementation is called with <c>next</c>.
/// </summary>
/// <param name = "_workTransType">The work transaction type.</param>
/// <param name = "_label">The license plate label being printed.</param>
public void printDocument(WHSWorkTransType _workTransType, WHSLicensePlateLabel _label)
{
    // Capture only labels with a work id while capture is enabled
    boolean capture = _label.WorkId
        && WHSParameters::find().aaxIsPreviewToWorkAttachmentEnabled();

    using (AAXWHSLabelCaptureScope scope = AAXWHSLabelCaptureScope::newFromLabel(_label, capture))
    {
        next printDocument(_workTransType, _label);
    }
}

/// <summary>
/// Extends <c>printLabelToPrinter</c> to stage the ZPL label in the active capture scope
/// before the base implementation is called with <c>next</c>. Without an active scope the
/// label passes through unchanged.
/// </summary>
/// <param name = "_printerName">The target printer name.</param>
/// <param name = "_label">The ZPL label text.</param>
public static void printLabelToPrinter(Name _printerName, str _label)
{
    // Stage the label when a capture scope is active
    AAXWHSLabelCaptureScope scope = AAXWHSLabelCaptureScope::current();

    if (scope && _label)
    {
        scope.stageLabel(_printerName, _label);
    }

    next printLabelToPrinter(_printerName, _label);
}
